function liveHome(){return `${liveHeading('Família · início do Núcleo','Nosso jardim','Nosso propósito: Cultivar presença, respeito e apoio mútuo.').replace('</p></div>', '</p><p class="live-copy"><span class="live-badge">'+icon('ShieldCheck',16)+' <strong>Você administra este Núcleo.</strong></span></p></div>')}<div class="live-home-grid">${livePanel('Na agenda',liveEventRows(false)+liveRow('Abrir agenda','Tempo para o que importa',14,'CalendarDays'),'live-home-list')}${livePanel('No seu tempo',`${liveNotice()}${liveRow('Cada novidade no seu tempo','Notificações ainda não estão disponíveis',60,'Bell',true)}<p class="live-footnote">Nenhuma notificação real é entregue neste exemplo.</p>`,'live-home-list')}${livePanel('Núcleos onde estou',`<details class="live-home-nucleus" open><summary><span class="live-row-icon">${icon('House',18)}</span><span><strong>Nosso jardim</strong><small>Família · exemplo</small></span></summary><div class="live-avatar-line"><span class="live-avatar">AN</span>Ana · administradora · exemplo</div>${liveRow('Pessoas e participação','Cada pessoa tem seu lugar',73,'UsersRound')}</details><p class="live-footnote">A lista real respeita suas associações.</p>`,'live-home-list')}</div><div class="live-section-heading"><h4>O que estamos cultivando</h4><button class="live-text" data-go="18">Ver acordos ${icon('ArrowRight',16)}</button></div><div class="live-home-agreements">${liveAgreementCard('Conversar sem distrações','Proposta','Depois do jantar · exemplo',18,false)}${livePanel('Um convite com cuidado',`<p>Compartilhe um código e deixe espaço para a outra pessoa escolher.</p>${liveButton('Convidar alguém',58)}<p class="live-footnote">Ação disponível para administradores.</p>`)}</div>`;}
