function liveBlock(block,index){
 const title=escapeHtml(block.title),text=escapeHtml(block.text);
 if(['field','area'].includes(block.type))return productField(block.title,`preview-${index}`,{area:block.type==='area',placeholder:block.text});
 if(block.type==='pick')return `<fieldset class="live-choice"><legend>${title}</legend><div>${block.text.split('|').map(option=>`<button type="button" data-local-tab aria-pressed="false">${escapeHtml(option)}</button>`).join('')}</div></fieldset>`;
 if(block.type==='tabs')return `<nav class="live-tabs" aria-label="Seções da composição">${block.text.split('|').map((option,position)=>`<button data-local-tab aria-pressed="${position===0}">${escapeHtml(option)}</button>`).join('')}</nav>`;
 if(block.type==='note')return `<p class="live-info">${text}</p>`;
 if(block.type==='avatar')return `<div class="live-account-profile"><span class="live-portrait">AN</span><h4>${title}</h4><p>${text}</p></div>`;
 if(block.type==='media')return `<section class="live-media-placeholder">${icon('Image',35)}<h4>${title}</h4><p>${text}</p>${liveNotice()}</section>`;
 return `<section class="live-context-section"><h4>${title}</h4><p>${text}</p>${block.to?liveButton('Conferir contexto',block.to,true):''}</section>`;
}
