 if([1,2,3,4,5].includes(screen.id))return `<div data-local-content>${livePublicContent(screen)}</div>`;
 let content;
 if([16,17].includes(screen.id))content=`<form data-local-form="preview">${productField('Título','event-title',{max:100,placeholder:'Encontro em família · exemplo'})}${productField('Intenção do momento · opcional','event-description',{area:true,placeholder:'Uma pausa para estarmos juntos.'})}<div class="live-grid">${productField('Início','event-start',{type:'datetime-local'})}${productField('Término','event-end',{type:'datetime-local'})}</div><p class="live-info">Fuso do dispositivo visível no aplicativo. Mudar o horário pede nova resposta aos demais participantes.</p><button class="live-button" type="submit">Conferir exemplo ${icon('ArrowRight',16)}</button></form>`;
 else if(screen.id===15)content=`${liveBadge('Sua resposta está pendente','orange')}<h4>Café e conversa · exemplo</h4><dl class="live-terms"><div><dt>Quando</dt><dd>16 de outubro · 16h00 às 17h00 · exemplo</dd></div><div><dt>Intenção</dt><dd>Uma pausa para escutar como foi a semana.</dd></div><div><dt>Sua participação</dt><dd>Somente você decide sua presença.</dd></div></dl><div class="live-actions"><button class="live-button" data-demo="attendance">Posso participar · exemplo</button><button class="live-button live-button-secondary" data-demo="attendance">Não posso · exemplo</button></div>${liveButton('Editar evento',17,true,true)}`;
 else if(screen.chapter===3)content=`${screen.status==='Planejada'?liveNotice():''}<div class="live-context-columns"><section>${screen.blocks.map(liveBlock).join('')}</section><aside class="live-detail-panel"><p class="live-kicker">Seu lugar aqui</p><h4>Escolhas com contexto.</h4><p>Participação, situação do acordo e etapa individual são informações diferentes.</p><p>Os termos precisam ser conhecidos antes do aceite. Nenhuma pessoa decide por outra.</p>${liveNotice()}<p>Evolução individual e passagens de etapa ainda serão definidas.</p></aside></div>${liveActions(screen)}`;
 else if(screen.id===59)return liveInvitations(screen);
 else if(screen.id===67)content=`<form data-local-form="preview"><label class="live-check"><input type="checkbox"><span><strong>Ocultar autoria após sair</strong><small>A preferência vale somente para as próximas saídas.</small></span></label><p class="live-info">Humor, notas e interações compartilhadas permanecem. Texto e contexto podem identificar você. Saídas anteriores não são modificadas automaticamente.</p><button class="live-button" type="submit">Salvar preferência · exemplo</button></form>${liveNotice()}<p>Visibilidade por campo, mídia e perfis têm contratos próprios.</p>${liveButton('Suporte sobre meus dados',70,true)}`;
 else if(screen.id===69)content=`<p>Dados ilustrativos de uma conta. A prévia não consulta credenciais.</p>${liveRow('Recuperar acesso','Solicitar um novo link',4,'LockKeyhole')}${liveRow('Confirmar e-mail','Conferir a confirmação',3,'Check')}${liveButton('Abrir área de Conta',69,true)}`;
 else if(screen.id===69)content=`${screen.blocks.map(liveBlock).join('')}<button class="live-button live-button-danger" data-atlas-modal data-live-delete-account>${icon('TriangleAlert',18)}Apagar minha conta ${liveModalLabel}</button>${liveActions(screen)}`;
 else if(screen.id===71)content=`${screen.blocks.map(liveBlock).join('')}<div class="live-actions"><button class="live-button" data-atlas-modal data-live-leave-confirm>Revisar minha saída ${liveModalLabel}</button>${liveButton('Conferir minha preferência',67,true)}${liveButton('Voltar sem sair',13,true)}</div>`;
 else content=`${screen.status==='Planejada'?liveNotice():''}${screen.blocks.map(liveBlock).join('')}${liveActions(screen)}`;
 return `<div data-local-content>${liveHeading(chapters[screen.chapter],screen.title,screen.subtitle)}${content}<p class="live-footnote">Prévia local. Nenhuma informação é enviada, alterada ou salva.</p></div>`;
