 let content;if(interactive&&previewState!=='content')content=liveState(screen);else if([6,7,8,9,10,11].includes(screen.id))content=`<section class="live-onboarding" data-local-content>${liveOnboarding(screen)}</section>`;else if(screen.id===12)content=liveNuclei();else if(screen.id===13)content=liveHome();else if([14,15,16,17].includes(screen.id))content=liveCalendar(screen);else if(screen.chapter===3)content=liveAgreements(screen);else if(screen.id===73)content=livePeople();else if([58,59].includes(screen.id))content=liveInvitations(screen);else if([66,67,68,69,70,71].includes(screen.id))content=liveSettings(screen);else content=liveFuture(screen);
