 if(target.hasAttribute('data-live-remove-event')){showLiveDialog('<p>Remover o evento apaga também as respostas de presença. No aplicativo essa ação não pode ser desfeita.</p><form data-local-form="preview"><label class="live-check"><input type="checkbox" required><span>Entendi que o evento e suas respostas serão removidos.</span></label><button class="live-button live-button-danger" type="submit">Confirmar remoção · exemplo</button></form>','Confirmar remoção');return;}
