 if(target.hasAttribute('data-atlas-menu')){target.setAttribute('aria-expanded','true');showLiveDialog(`<nav class="live-menu-groups" aria-label="Mais áreas e preferências">${currentAreas.slice(4).map(([label,id,symbol])=>liveRow(label,[38,44,55].includes(id)?'Esboço de funcionalidade':'Abrir área',id,symbol)).join('')}${liveRow('Seus Núcleos','Escolher um espaço',12,'UsersRound')}${liveRow('Conta','Seu acesso ao Nós',69,'LockKeyhole')}${liveRow('Preferências e ajuda','Privacidade e suporte',66,'Settings')}</nav>`,'Mais áreas e preferências');return;}
 if(target.hasAttribute('data-live-select-event')){const workspace=target.closest('.live-calendar-layout');workspace.querySelectorAll('[data-live-select-event]').forEach(button=>button.setAttribute('aria-pressed',String(button===target)));const title=workspace.querySelector('aside .live-panel>h4');if(title)title.textContent=target.querySelector('strong').textContent;workspace.querySelector('aside').scrollIntoView({block:'nearest'});return;}
 if(target.hasAttribute('data-live-proposal')){showLiveDialog(`<p class="live-copy">Uma conversa pode virar um combinado. Enviar uma proposta não registra aceite.</p><form data-local-form="preview"><label class="live-field">Categoria<select name="category"><option>Hábito</option><option>Experiência</option></select></label>${productField('O que vamos fazer?','habit-title',{max:100})}${productField('Como será?','habit-description',{area:true})}<div class="live-grid">${productField('Quando?','habit-timing',{max:120,placeholder:'Ex.: depois do jantar'})}${productField('Com que frequência?','habit-frequency',{max:120,placeholder:'Ex.: diária'})}</div>${productField('Duração do teste (dias)','habit-trial',{type:'number',placeholder:'7 a 30 dias'})}<p class="live-info">Um administrador organiza o teste e a ativação. Cada pessoa decide se participa. Categoria e evolução individual são informações distintas.</p><button type="submit" class="live-button">Conferir proposta · exemplo</button></form><p class="live-footnote">O fluxo guiado de necessidade e compreensão é futuro.</p>${liveButton('Explorar fluxo guiado · esboço',19,true)}`,'Nova proposta');return;}
